import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788283327000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>MEALIE_URL</code></td><td>yes</td><td>—</td><td>Base URL of the Mealie instance, e.g. <code>https://mealie.example.com</code></td></tr><tr><td><code>MEALIE_API_TOKEN</code></td><td>yes</td><td>—</td><td>API token from Settings → API Tokens; acts as the user who created it</td></tr><tr><td><code>MEALIE_READ_ONLY</code></td><td>no</td><td><code>false</code></td><td>Exactly <code>true</code> registers only the 18 read tools</td></tr><tr><td><code>MEALIE_ACCEPT_LANGUAGE</code></td><td>no</td><td>—</td><td>Sent as <code>accept-language</code>, e.g. <code>de-DE</code>; localises unit and label names</td></tr><tr><td><code>MEALIE_INSECURE_TLS</code></td><td>no</td><td><code>false</code></td><td>Exactly <code>true</code> accepts a self-signed certificate — scoped to this connection only</td></tr><tr><td><code>ELICITATION</code></td><td>no</td><td><code>true</code></td><td><code>false</code> replaces the approval dialog with the two-call token. <strong>Not prefixed</strong></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">The booleans compare against the literal string <code>true</code></p><p><code>MEALIE_READ_ONLY</code> and <code>MEALIE_INSECURE_TLS</code> are only on when their value is exactly the string <code>true</code>. <code>1</code>, <code>yes</code>, <code>True</code> — any typo — fails <strong>off</strong>. The startup banner on stderr reports the mode actually in effect; check it after changing the configuration.</p></div><h2 id="elicitation" tabindex="-1"><code>ELICITATION</code> <a class="header-anchor" href="#elicitation" aria-label="Permalink to “ELICITATION”">​</a></h2><p>Whether a client that <em>can</em> show a dialog is asked before a guarded tool acts. Default <code>true</code>. <code>false</code> takes the two-call-token path instead — it does not remove the guard, and a server started with it off prints one line saying so.</p><p>Two ways it differs from every other variable here:</p><ul><li><strong>No prefix.</strong> One <code>export ELICITATION=false</code> reaches every MCP server in the same environment, not just this one. That is the point of it and also its risk; see <a href="/guide/approval">Asking a person</a>.</li><li><strong>Fatal on anything else.</strong> Where the <code>MEALIE_*</code> booleans fail <em>off</em> on a typo, this one stops the server with exit code 1. It is the only variable here that defaults to <em>on</em>, and a typo that fell back to the default would leave the dialog running while you believed it was off.</li></ul><p>Values are trimmed and matched case-insensitively. It is read <em>after</em><code>MEALIE_API_TOKEN</code> is deleted from <code>process.env</code>, so the fatal path cannot leave the token sitting there for a crash reporter.</p><h2 id="mealie-url" tabindex="-1"><code>MEALIE_URL</code> <a class="header-anchor" href="#mealie-url" aria-label="Permalink to “MEALIE_URL”">​</a></h2><p>Must be an absolute <code>http://</code> or <code>https://</code> URL. The server exits at startup if the value</p><ul><li>does not parse as a URL,</li><li>uses a scheme other than <code>http</code> or <code>https</code>,</li><li>embeds credentials (<code>https://user:pass@…</code> — use <code>MEALIE_API_TOKEN</code> instead), or</li><li>carries a query string or fragment (either would silently corrupt every request URL built from the base).</li></ul><p>Plain <code>http://</code> to a non-loopback host starts, but prints a warning: the token would travel unencrypted.</p><h2 id="mealie-api-token" tabindex="-1"><code>MEALIE_API_TOKEN</code> <a class="header-anchor" href="#mealie-api-token" aria-label="Permalink to “MEALIE_API_TOKEN”">​</a></h2><p>Created in Mealie under <strong>Settings → API Tokens</strong>. It is a secret: it acts as the user who created it and inherits that user&#39;s group, household and permissions — use a dedicated, non-admin user (see the <a href="/guide/security#trust-model">trust model</a>).</p><p>The token is <strong>deleted from the process environment</strong> as soon as it has been read, so child processes cannot pick it up out of <code>/proc/&lt;pid&gt;/environ</code>.</p><h2 id="mealie-read-only" tabindex="-1"><code>MEALIE_READ_ONLY</code> <a class="header-anchor" href="#mealie-read-only" aria-label="Permalink to “MEALIE_READ_ONLY”">​</a></h2><p>Exactly <code>true</code> registers only the 18 read tools; the 34 write and import tools are not registered at all, so a model cannot call them and does not see them in the catalog.</p><h2 id="mealie-accept-language" tabindex="-1"><code>MEALIE_ACCEPT_LANGUAGE</code> <a class="header-anchor" href="#mealie-accept-language" aria-label="Permalink to “MEALIE_ACCEPT_LANGUAGE”">​</a></h2><p>Mealie honours the <code>accept-language</code> header on nearly every endpoint; it localises unit names, label names and validation messages. Unset, the choice is left to the server default.</p><h2 id="mealie-insecure-tls" tabindex="-1"><code>MEALIE_INSECURE_TLS</code> <a class="header-anchor" href="#mealie-insecure-tls" aria-label="Permalink to “MEALIE_INSECURE_TLS”">​</a></h2><p>Exactly <code>true</code> accepts a self-signed certificate. The override is scoped to the Mealie connection — it does not set <code>NODE_TLS_REJECT_UNAUTHORIZED</code> and does not affect any other TLS connection the process makes.</p><h2 id="missing-configuration" tabindex="-1">Missing configuration <a class="header-anchor" href="#missing-configuration" aria-label="Permalink to “Missing configuration”">​</a></h2><p>Missing credentials are a warning, not a fatal error: the server still completes the MCP handshake and answers <code>tools/list</code>, so registries and sandbox inspectors can introspect it. Every API call then fails with setup instructions. A malformed <code>MEALIE_URL</code> is the exception and exits immediately — that one could send the token to the wrong host.</p><h2 id="narrowing-the-tool-list" tabindex="-1">Narrowing the tool list <a class="header-anchor" href="#narrowing-the-tool-list" aria-label="Permalink to “Narrowing the tool list”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>MEALIE_ALLOW_TOOLS</code></td><td>no</td><td>Tool names, <code>list_*</code> prefixes or <code>essential</code>; only these register</td></tr><tr><td><code>MEALIE_DENY_TOOLS</code></td><td>no</td><td>Same syntax; subtracted from whatever the allow list left</td></tr></tbody></table><p>Both are comma-separated. Each entry is either an exact tool name or a prefix with a single trailing <code>*</code>. Entries are trimmed and matched case-insensitively; empty entries are ignored, and a value that is empty or only whitespace counts as unset — <code>MEALIE_ALLOW_TOOLS=</code> in a compose file does not mean &quot;allow nothing&quot;. <code>essential</code> is recognised only in the allow list, and selects <code>search_recipes</code>, <code>get_recipe</code>, <code>import_recipe_from_url</code>, <code>create_recipe</code>, <code>get_todays_meals</code>, <code>create_mealplan_entry</code>, <code>list_shopping_lists</code>, <code>add_recipe_to_shopping_list</code>.</p><p><strong>An entry that matches no tool aborts startup</strong>, naming the entry and listing the valid names, as does a malformed pattern such as <code>*_x</code> or <code>list_*_x</code>. The alternative — ignoring the entry — leaves a tool missing from <code>tools/list</code> with nothing pointing at the cause. If both lists together remove everything, the server refuses to start rather than offering an empty tool list.</p><p>Under <code>MEALIE_READ_ONLY</code>, an exact write-tool name in the allow list is an error naming the read-only setting rather than &quot;unknown tool&quot;; a pattern covering write tools is accepted and merely contributes nothing, with a warning on stderr. Deny entries are exempt: denying an already-suppressed tool is how a defensive list is written.</p>`,28)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};